import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang'

export const mapVehicleDamagePhotos = (damagePhotos) => {
  const mappedArr = []
  for (const key in damagePhotos) {
    mappedArr.push(damagePhotos[key].original)
  }

  return mappedArr
}

export const getVehicleDamageForm = (data) => {
  return {
    fields: [
      {
        type: 'uploadBulkImgButton',
        label: LANG_STRINGS.photo,
        guide: true,
        hideGuideIcon: true,
        placeholder: LANG_STRINGS.upload,
        defaultValue: mapVehicleDamagePhotos(data.damage_photos),
        name: 'damage_photos'
      },
      {
        type: 'textarea',
        label: LANG_STRINGS.information,
        defaultValue: data.damage_remarks,
        name: 'damage_remarks',
        minLength: 20,
        maxLength: 500,
        lengthErr: ERROR_LANG.min20max500Character,
        border: true,
        className: 'input-field'
      }
    ]
  }
}
