import { useCallback, useRef, useState, forwardRef, useImperativeHandle } from 'react'
import moment from 'moment'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText, InnerForm } from '../../../../../components'
import CustomCheckbox from '../../../../../components/CustomCheckbox'
import InfoModal from '../../../../../components/InfoModal'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { getVehicleDamageForm } from './constants'
import { VehicleDamagePhotosStyle } from './index.style'
import { getFileNameFromUrl } from '../../../../../helpers/utility'
import { isEmpty } from 'lodash'

function VehicleDamagePhotos ({ damageData = {} }, parentRef) {
  const [isDamaged, setIsDamaged] = useState(!!damageData.damage_remarks || !isEmpty(damageData?.damage_photos))
  const [showDamageGuide, setShowDamageGuide] = useState(false)
  const damageFormRef = useRef('')

  useImperativeHandle(parentRef, () => ({
    validateDamagePhoto: async (e) => {
      let damageData = null
      if (isDamaged) {
        damageData = await damageFormRef.current.handleSubmit(e)
        if (damageData && Object.keys(damageData).length > 0) {
          const damagePhotos = [...damageData.damage_photos]
          const mappedPhotos = {}
          damagePhotos.forEach(url => {
            const uuid = getFileNameFromUrl(url).split('.')[0]
            mappedPhotos[uuid] = {
              id: uuid,
              original: url,
              timestamp: moment().format('YYYY-MM-DD HH:MM')
            }
          })
          damageData.damage_photos = {
            ...mappedPhotos
          }
        }
      }
      return {
        isDamaged,
        ...damageData
      }
    }
  }))

  const handleOnGuideClick = useCallback(() => {
    setShowDamageGuide(!showDamageGuide)
  }, [showDamageGuide])

  return (
    <VehicleDamagePhotosStyle>
      <Row justify='space-between'>
        <CustomText
          color={AgentColorPallette.black}
          size='15px'
          weight={800}
        >
          {LANG_STRINGS.congenitalDisability}
        </CustomText>
        <CustomCheckbox
          color={AgentColorPallette.black}
          isChecked={isDamaged}
          onChange={() => setIsDamaged(!isDamaged)}
          name='hardCopy'
          id='hardCopy'
        />
      </Row>
      <CustomText bottom='10px' color={AgentColorPallette.fontSecondary} top='4px'>
        {LANG_STRINGS.selectThisIfCongenitalDamage}&nbsp;&nbsp;
      </CustomText>
      {
        isDamaged &&
          <div>
            <InnerForm
              formData={getVehicleDamageForm(damageData)}
              ref={damageFormRef}
              onGuideClick={handleOnGuideClick}
            />
          </div>
      }
      {
        showDamageGuide &&
          <InfoModal
            showModal={showDamageGuide}
            onCloseModal={() => setShowDamageGuide(false)}
          >
            <div>
              <CustomText
                size='13px'
                weight={800}
              >
                {LANG_STRINGS.photoUploadGuide}
              </CustomText>
              <ol>
                <li>
                  <CustomText
                    size='13px'
                    weight={600}
                  >
                    {LANG_STRINGS.youCanUploadMoreThanOnePhoto}
                  </CustomText>
                </li>
                <li>
                  <CustomText
                    top='6px'
                    size='13px'
                    weight={600}
                  >
                    {LANG_STRINGS.makeSurePhotoIsGood}
                  </CustomText>
                </li>
              </ol>
              <CustomText
                top='10px'
                size='15px'
                weight='700'
                color={AgentColorPallette.aqua}
                textAlign='right'
                onClick={() => setShowDamageGuide(false)}
              >
                {LANG_STRINGS.understand}
              </CustomText>
            </div>
          </InfoModal>
      }
    </VehicleDamagePhotosStyle>
  )
}

export default forwardRef(VehicleDamagePhotos)
