import { Component } from 'react'
import { connect } from 'react-redux'
import { get } from 'lodash/object'
import { Container } from '../../../../components'
import customerActions from '../../../../redux/customer/actions'
import { LANG_STRINGS } from '../../../../lang'
import PolicyCustAgentForm from '../../../../components/PolicyCustAgentForm'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import { getCreatePolicyQuotationBdy } from '../../../../helpers/getPackageBody'
import { setToLocalStorage, removeFromLocalStorageData } from '../../../../helpers/localstorage'
import { CUSTOMER_FLOW } from '../../../../constants/cookies'
import policyActions from '../../../../redux/policy/action'

const {
  getCustomerPolicy, updateCustomerPolicyData, resetCustomerStore,
  getCustomerDraftDetailsReq, updateCustomerDraftQuoteReq
} = customerActions
const { getRenewalQuoatationData, resetPolicyStore, submitRenewalQuoatationData } = policyActions
export class CustomerPolicyForm extends Component {
  constructor (props) {
    super(props)
    this.state = {
      policyQuotation: {},
      step: '1'
    }

    this.finalData = {}
  }

  componentDidMount () {
    this.policyId = get(this.props, 'match.params.policyId', '')
    this.draftQuoteId = get(this.props, 'match.params.draftQuoteId', '')
    this.renewalOrgPolicyId = get(this.props, 'match.params.orgPolicyId', '')
    setToLocalStorage(CUSTOMER_FLOW, 'true')
    if (window.location.href.includes('renewal')) {
      this.isRenewalFlow = true
      this.props.getRenewalQuoatationData({
        policyId: this.renewalOrgPolicyId
      })
      return
    }
    this.setState({
      step: get(this.props, 'match.params.step', '')
    })
    if (this.policyId) {
      // this getting the details for the customer Data
      this.props.getCustomerPolicy(this.props.match.params.policyId)
    } else if (this.draftQuoteId) {
      this.props.getCustomerDraftDetailsReq({
        draftQuoteId: this.props.match.params.draftQuoteId
      })
    }
    // setToLocalStorage(CUSTOMER_FLOW, 'true')
  }

  componentWillReceiveProps (nextProps) {
    const {
      customerPolicy, customerPolicyDataStatus, resetCustomerStore,
      updateCustomerPolicyStatus, updateCustomerPolicyError,
      getCustomerDraftQuoteDetailStatus, getCustomerDraftQuoteDetailData,
      updateCustomerDraftQuoteStatus
    } = nextProps

    if (customerPolicyDataStatus === 'success') {
      if (customerPolicy.migrated_draft_id) {
        this.props.history.replace(`/customer/draft/policy/${customerPolicy.migrated_draft_id}/1/form`)
      }
      this.setState({
        policyQuotation: customerPolicy
      })
      resetCustomerStore(['customerPolicyDataStatus', 'customerPolicy'])
    }

    if (updateCustomerPolicyStatus === 'success') {
      removeFromLocalStorageData(CUSTOMER_FLOW)
      this.props.history.push({
        pathname: `/customer/policy/${this.props.match.params.policyId}/2/summary`
      })
      resetCustomerStore(['updateCustomerPolicyStatus'])
    } else if (updateCustomerPolicyError && updateCustomerPolicyStatus) {
      NotificationManager.error(updateCustomerPolicyStatus)
      resetCustomerStore(['updateCustomerPolicyStatus'])
    }

    if (getCustomerDraftQuoteDetailStatus === 'success') {
      if (getCustomerDraftQuoteDetailData.policy_application_id) {
        this.props.history.replace(`/customer/policy/${getCustomerDraftQuoteDetailData.policy_application_id}`)
        return
      }
      const policyDetails = getCustomerDraftQuoteDetailData?.policy_details
      const totalBill = policyDetails?.total_bill || policyDetails?.package_data?.total_bill
      const quote = {
        ...policyDetails?.package_data,
        policy_detail: {
          ...policyDetails
        },
        product: {
          ...policyDetails.package_data
        },
        premium: {
          period: 12,
          amount: policyDetails?.package_data?.basic_premium
        },
        customer_data: policyDetails?.customer_data,
        total_premium: totalBill,
        draft_id: this.draftQuoteId,
        total_bill: totalBill
      }
      this.setState({
        policyQuotation: quote
      })
      resetCustomerStore(['getCustomerDraftQuoteDetailStatus'])
    }

    if (updateCustomerDraftQuoteStatus === 'success') {
      resetCustomerStore(['updateCustomerDraftQuoteStatus'])
      this.props.history.push({
        pathname: `/customer/draft/policy/${this.draftQuoteId}/2/summary`
      })
    }

    // also show api error if api gives 400
  }

  componentDidUpdate () {
    const {
      resetPolicyStore, submitRenewalQuotationStatus, getRenewalQuotationStatus,
      getRenewalQuotationData = {}
    } = this.props
    if (submitRenewalQuotationStatus === 'success') {
      this.props.history.push({
        pathname: `/customer/renewal/policy/summary/${this.policyId}/2`
      })
      resetPolicyStore(['submitRenewalQuotationStatus'])
    } else if (submitRenewalQuotationStatus) {
      NotificationManager.error(submitRenewalQuotationStatus)
      resetPolicyStore(['submitRenewalQuotationStatus'])
    }

    if (getRenewalQuotationStatus === 'success' && (getRenewalQuotationData?.renewal_policy_status === 'INITIATED')) {
      this.props.getCustomerPolicy(this.policyId)
      resetPolicyStore(['getRenewalQuotationStatus'])
    } else if (getRenewalQuotationStatus) {
      resetPolicyStore(['getRenewalQuotationStatus'])
    }
  }

  handleFormSubmit = (data) => {
    this.finalData = {
      ...data,
      token: this.props.match.params.policyId
    }
    if (this.isRenewalFlow) {
      let hardCopy = {}
      if (this.finalData.hard_copy_required) {
        hardCopy = {
          hard_copy_required: this.finalData.hard_copy_required,
          hard_copy_sent_to: this.finalData.hard_copy_sent_to,
          hard_copy_enabled: this.finalData.hard_copy_enabled,
          hard_copy_address: this.finalData.hard_copy_address
        }
      }
      this.props.submitRenewalQuoatationData({
        policyId: this.renewalOrgPolicyId,
        customer_data: this.finalData.customer_data,
        ktp_no: this.finalData.ktp_no,
        ktp_url: this.finalData.ktp_url,
        stnk_url: this.finalData.ktp_url,
        edit_existing_policy: false,
        previous_certificate_url: this.finalData.previous_certificate_url,
        new_policy_ref_id: this.policyId,
        ...hardCopy
      })
      return
    }
    if (this.draftQuoteId) {
      this.props.updateCustomerDraftQuoteReq({
        section: 'mv_quote_summary',
        sub_section: 'mv_quote_summary',
        data: {
          ...this.finalData,
          ...(this.finalData.addons_data)
        },
        draftQuoteId: this.draftQuoteId
      })
    } else {
      this.props.updateCustomerPolicyData(this.finalData)
    }
  }

  render () {
    const {
      customerPolicyLoader, getRenewalQuotationLoading, submitRenewalQuotationLoading,
      updateCustomerLoader, getRenewalQuotationData = {}, customerPolicy, getCustomerDraftQuoteDetailLoading,
      updateCustomerDraftQuoteLoading
    } = this.props

    const { policyQuotation, step } = this.state
    const customerQuotationData = (this.isRenewalFlow && (getRenewalQuotationData?.renewal_policy_status !== 'INITIATED')) ? {
      ...getRenewalQuotationData,
      previous_certificate_url: getRenewalQuotationData?.document_url
    } : {
      id: (policyQuotation.id || customerPolicy.id),
      ...(policyQuotation.product || customerPolicy.product),
      ...getCreatePolicyQuotationBdy({
        policyData: {
          ...(policyQuotation.policy_detail || customerPolicy.policy_detail),
          admin_fee: policyQuotation.admin_fee || customerPolicy.admin_fee,
          customer_data: policyQuotation.customer_data || customerPolicy.customer_data
        },
        packageData: policyQuotation.product || customerPolicy.product,
        discount: policyQuotation.policy_detail?.discount || (customerPolicy.discount)
      })
    }
    const isRender = (customerPolicyLoader === false) || (getRenewalQuotationLoading === false) || (getCustomerDraftQuoteDetailLoading === false)

    return (
      <Container
        mitraHeader
        hideBottomTabs
        loader={
          customerPolicyLoader || updateCustomerLoader || submitRenewalQuotationLoading || updateCustomerDraftQuoteLoading
        }
      >
        {
          isRender &&
          (customerQuotationData?.id || customerQuotationData?.chasis_number || customerQuotationData.draft_id) && !customerQuotationData.migrated_draft_id && (
            <PolicyCustAgentForm
              stepTotal='4'
              stepCurrent={step}
              isRenewalFlow={this.isRenewalFlow}
              stepTitle={LANG_STRINGS.fillInTheVehicleData}
              onSubmitForm={this.handleFormSubmit}
              policyFormData={customerQuotationData}
            />
          )
        }
        <NotificationContainer />
      </Container>
    )
  }
}

export default connect(
  (state) => ({
    customerPolicy: state.Customer.customerPolicyData,
    customerPolicyDataStatus: state.Customer.customerPolicyDataStatus,
    customerPolicyLoader: state.Loading.GET_CUSTOMER_POLICY,
    submitRenewalQuotationLoading: state.Loading.SUBMIT_RENEWAL_QUOTATION_DATA,
    getRenewalQuotationLoading: state.Loading.GET_RENEWAL_QUOTATION_DATA,
    updateCustomerLoader: state.Loading.UPDATE_CUSTOMER_POLICY,
    updateCustomerPolicyStatus: state.Customer.updateCustomerPolicyStatus,
    getRenewalQuotationData: state.Policy.getRenewalQuotationData,
    submitRenewalQuotationStatus: state.Policy.submitRenewalQuotationStatus,
    getRenewalQuotationStatus: state.Policy.getRenewalQuotationStatus,
    getCustomerDraftQuoteDetailData: state.Customer.getCustomerDraftQuoteDetailData,
    getCustomerDraftQuoteDetailLoading: state.Loading.GET_CUSTOMER_DRAFT_QUOTE_DETAIL,
    getCustomerDraftQuoteDetailStatus: state.Customer.getCustomerDraftQuoteDetailStatus,
    updateCustomerDraftQuoteLoading: state.Loading.UPDATE_CUSTOMER_DRAFT_QUOTE,
    updateCustomerDraftQuoteData: state.Customer.updateCustomerDraftQuoteData,
    updateCustomerDraftQuoteStatus: state.Customer.updateCustomerDraftQuoteStatus,
    customerError: state.Error.GET_CUSTOMER_POLICY,
    updateCustomerPolicyError: state.Error.UPDATE_CUSTOMER_POLICY
  }),
  {
    getCustomerPolicy,
    updateCustomerPolicyData,
    submitRenewalQuoatationData,
    updateCustomerDraftQuoteReq,
    getCustomerDraftDetailsReq,
    getRenewalQuoatationData,
    resetPolicyStore,
    resetCustomerStore
  }
)(CustomerPolicyForm)
