import { ConfigUrl } from '../../configs/url'

export const COMMON_ACTIONS = {
  GET_CITIES_REQUEST: 'GET_CITIES_REQUEST',
  GET_CITIES: 'GET_CITIES',

  GET_INVOICE_DETAIL_REQUEST: 'GET_INVOICE_DETAIL_REQUEST',
  GET_INVOICE_DETAIL: 'GET_INVOICE_DETAIL',

  VALIDATE_CHASSIS_NO_REQUEST: 'VALIDATE_CHASSIS_NO_REQUEST',
  VALIDATE_CHASSIS_NO: 'VALIDATE_CHASSIS_NO',

  GET_SURVEY_FORM_REQUEST: 'GET_SURVEY_FORM_REQUEST',
  GET_SURVEY_FORM: 'GET_SURVEY_FORM',

  OFFLINE_QUOTE_DETAIL_REQUEST: 'OFFLINE_QUOTE_DETAIL_REQUEST',
  OFFLINE_QUOTE_DETAIL: 'OFFLINE_QUOTE_DETAIL',

  UPDATE_DRAFT_QUOTATION_REQUEST: 'UPDATE_DRAFT_QUOTATION_REQUEST',
  UPDATE_DRAFT_QUOTATION: 'UPDATE_DRAFT_QUOTATION'

}

export const getCitiesAction = (payload = {}) => ({
  type: COMMON_ACTIONS.GET_CITIES_REQUEST,
  payload: {
    method: 'GET',
    url: ConfigUrl.getPropertyCities(payload.province)
  }
})

export const getInvoiceDetail = (payload = {}) => ({
  type: COMMON_ACTIONS.GET_INVOICE_DETAIL_REQUEST,
  payload: {
    method: 'GET',
    url: ConfigUrl.getInvoiceDetail(payload.invoiceId)
  }
})

export const validateChassisNumber = (payload) => ({
  type: COMMON_ACTIONS.VALIDATE_CHASSIS_NO_REQUEST,
  payload: {
    ...payload,
    method: 'post',
    url: ConfigUrl.validateChassisNumberApi
  }
})

export const getOfflineQuoteDetails = (payload = {}) => ({
  type: COMMON_ACTIONS.OFFLINE_QUOTE_DETAIL_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.offlineQuoteDetailApi(payload.quoteId)
  }
})

export const getSurveyForm = (payload) => ({
  type: COMMON_ACTIONS.GET_SURVEY_FORM_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.getProviderSurvey()
  }
})

export const updateDraftQuotesReq = (payload) => ({
  type: COMMON_ACTIONS.UPDATE_DRAFT_QUOTATION_REQUEST,
  payload: {
    ...payload,
    method: 'post',
    url: ConfigUrl.draftPolicyUpdateApi(payload.draftQuoteId)
  }
})
