import get from 'lodash/get'
import isEmpty from 'lodash/isEmpty'
import { useCallback, useEffect, useRef } from 'react'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { getCustomerFormData } from '../../../../containers/Private/Application/constants'
import AddressForm from '../../../AddressForm'
import CustomText from '../../../CustomText'
import InnerForm from '../../../InnerForm'

function CustomerDataForm (props) {
  const {
    handleGetSubmitMethods, preFormData, onGuideClick,
    onCustomerAddressChange, onCustomerFormChange,
    isOldQuotation, isRenewalFlow, title
  } = props

  const customerDataForm = getCustomerFormData({
    ...preFormData
  }, isOldQuotation, isRenewalFlow)
  const customerDataFormRef = useRef('')
  const customerAddrSubmitRef = useRef()

  const handleSubmit = useCallback(async (e) => {
    const responseCustomerDataForm = await customerDataFormRef.current.handleSubmit(e)
    const customerAddress = await customerAddrSubmitRef.current(e)
    if (responseCustomerDataForm && Object.keys(responseCustomerDataForm).length > 0 && !isEmpty(customerAddress)) {
      const finalData = {
        ...responseCustomerDataForm,
        customer_address: {
          ...customerAddress
        }
      }
      delete finalData.errorField
      return {
        customer_data: {
          ...finalData
        },
        ktp_url: typeof finalData.ktp === 'object' ? finalData.ktp.ktp : finalData.ktp,
        ktp_no: finalData.ktp_no
      }
    }
  }, [])

  const handleGetAddressSubmit = useCallback((type, onSubmit, getAddr) => {
    customerAddrSubmitRef.current = onSubmit
  }, [])

  useEffect(() => {
    handleGetSubmitMethods('customer-data-form',
      handleSubmit)
  }, [handleGetSubmitMethods, handleSubmit])

  return (
    <>
      <CustomText
        size='16px'
        weight={800}
        color={AgentColorPallette.black}
        top='8px'
        bottom='5px'
      >
        {title}
      </CustomText>
      <InnerForm
        formData={customerDataForm}
        ref={customerDataFormRef}
        onGuideClick={onGuideClick}
        onInputChange={onCustomerFormChange}
      />
      <AddressForm
        addressType='customer-address'
        address={get(preFormData, 'customer_data.customer_address', {})}
        handleGetAddressSubmit={handleGetAddressSubmit}
        onAddressChange={onCustomerAddressChange}
      />
    </>
  )
}

export default CustomerDataForm
