import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../../state/commonState/reducers'

// this is the context used by the all pages
export const CommonContext = createContext()

// provider provide the update context value
export const CommonContextProvider = (props) => {
  // use reducer provides the initial state and dispatch function
  // to all nested children [state, dispatch]

  return (
    <CommonContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </CommonContext.Provider>
  )
}

// use to read the value from the global state
export const useCommonContextValue = () => useContext(CommonContext)
