import { Component } from 'react'
import PropTypes from 'prop-types'
import Modal from '../Modal'
import { DisplayFlexRCC, Row } from '../../commonStyle/index.style'
import Button from '../Button'
import { LANG_STRINGS } from '../../lang'
import { AgentColorPallette } from '../../configs/colorPallete'
import { ZoomImgStyle } from './index.style'
import { INPUT_FILE_TYPE } from '../../constants/file'

class ZoomEditImg extends Component {
  static propTypes = {
    showModal: PropTypes.bool,
    title: PropTypes.string,
    imgUrl: PropTypes.string,
    onClose: PropTypes.func,
    onChangeImg: PropTypes.func,
    onRemoveImg: PropTypes.func,
  }

  render() {
    const { title, showModal, onClose, imgUrl, onRemoveImg, name, onChangeImg } = this.props
    const inputName = `zoomImg_${name}`
    return (
      <Modal heading={title} isOpen={showModal} onClose={onClose}>
        <ZoomImgStyle>
          <DisplayFlexRCC>
            <img src={imgUrl} height="200px" alt="" className="zoom-img" />
          </DisplayFlexRCC>
          <Row align="center" justify="space-between" className="zoom-btns">
            <Button
              backgroundColor={AgentColorPallette.cyanBlue}
              color={AgentColorPallette.white}
              onClick={onRemoveImg}
            >
              {LANG_STRINGS.remove}
            </Button>
            &nbsp;&nbsp;&nbsp;
            <div className="zoom-img-change-btn">
              <input
                className="zoom-input-file"
                type="file"
                id={inputName}
                name={inputName}
                onChange={(e) => onChangeImg(e, inputName)}
                accept={INPUT_FILE_TYPE.IMAGE}
              />
              {LANG_STRINGS.change}
            </div>
          </Row>
        </ZoomImgStyle>
      </Modal>
    )
  }
}

export default ZoomEditImg
