import { createRef, Component } from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import { get } from 'lodash/object'
import { PolicyCustAgentFormStyle, VehicleImgGuideStyle } from './index.styles'
import { NotificationManager } from 'react-notifications'
import StepsHeader from '../StepsHeader'
import { ERROR_LANG, LANG_STRINGS } from '../../lang'
import AccessoriesWithImage from '../../containers/Private/Application/components/AccessoriessWithImage'
import { RequiredStar, Row } from '../../commonStyle/index.style'
import CustomText from '../CustomText'
import { AgentColorPallette } from '../../configs/colorPallete'
import { Upload } from '..'
import InnerForm from '../InnerForm'
import { getPolicyFormData } from '../../containers/Private/Application/constants'
import Button from '../Button'
import ImageGuideModal from './components/ImageGuideModal'
import {
  LIGHT_GOLD_BULB,
  STNK,
  KTP_IMG,
  VEHICLE_DASHBOARD_IMG,
  VEHICLE_FACE_IMG,
  VEHICLE_BACK_IMG,
  VEHICLE_RIGHT_FACE_IMG,
  VEHICLE_LEFT_FACE_IMG,
  CERTIFICATE_PREVIEW,
  DOCUMENT,
  SEARCH,
} from '../../images'
import SingleImgContainer from '../SingleImgContainer'
import ZoomEditImg from '../ZoomEditImgModal'
import policyActions from '../../redux/policy/action'
import LoadingActions from '../../redux/loading/action'
import ErrorActions from '../../redux/error/action'
import AppointmentLetter from './components/AppointmentLetter'
import moment from 'moment'
import isEmpty from 'lodash/isEmpty'
import { getFromLocalStorageData, setToLocalStorage } from '../../helpers/localstorage'
import { AGENT_MV_FORM_DATA, IS_SCROLL_START, VEHICLE_FORM_DATA } from '../../constants/cookies'
import { GlobalContext } from '../../contextProvider/GlobalContext'
import { saveCustomerData } from '../../state/globalState/actions'
import CustomerDataForm from './components/CustomerDataForm'
import HardCopySection from '../HardCopySection'
import isObject from 'lodash/isObject'
import { smoothScroll } from '../../helpers/smoothScroll'
import { SEND_TO_CUSTOMER } from '../../constants/hardCopy'
import WarningModal from '../WarningModal/index'
import VehicleChassisEdit from './components/VehicleChassisEdit'
import SurveySection from '../SurveySection'
import VehicleDamagePhotos from '../../containers/Private/Application/components/VehicleDamangePhotos'
import { INPUT_FILE_TYPE } from '../../constants/file'

const { getUploadLink, resetPolicyStore, validateChassisNumber } = policyActions
const { resetLoadingRedux } = LoadingActions
const { resetErrorRedux } = ErrorActions

export class PolicyCustAgentForm extends Component {
  static propTypes = {
    onSubmitForm: PropTypes.func,
    stepTitle: PropTypes.string,
    stepCurrent: PropTypes.number,
    stepTotal: PropTypes.number,
    isRenewalFlow: PropTypes.bool,
    policyFormData: PropTypes.object,
  }

  constructor(props) {
    super(props)
    const localData = getFromLocalStorageData(AGENT_MV_FORM_DATA)
    let policyFormData = props.policyFormData
    if (!isEmpty(localData) && !policyFormData.color) {
      policyFormData = localData
    }
    this.state = {
      images: policyFormData.images || {},
      finalData: {},
      showEditVehicleBtn: false,
      showChassisModal: {
        show: false,
        content: '',
      },
      editChassisModal: {
        show: false,
        data: {},
      },
      applicationData: {
        accessories: [],
        ...policyFormData,
      },
      isValidationChassisStart: false,
      appointmentLetterError: false,
      address: policyFormData.address,
      certificateError: '',
      isCustomerAddrSame: false,
      showZoomModal: false,
      selectedHardcopyType: policyFormData.hard_copy_sent_to || '',
      isPhotoRequired: props.isRenewalFlow ? false : get(policyFormData, 'photo_required', true),
      errorHardCopySelect: '',
    }
    this.customerDataFormSubmit = createRef()
    this.vehicleDamageFormSubmitRef = createRef()
    this.child = createRef()
    this.accessoriesRef = createRef()
    this.isCustomerForm = false
    this.clearChassisTimeOut = ''
    this.surveyDataFormSubmit = createRef()
    if (window.location.href.includes('customer/')) {
      this.isCustomerForm = true
    }
  }

  componentWillReceiveProps(nextProps) {
    const { resetPolicyStore, getUploadLinkError, uploadLinkStatus, uploadLink = {} } = nextProps
    if (nextProps.getUploadLinkError && nextProps.getUploadLinkLoading === false) {
      this.props.resetErrorRedux(['GET_UPLOAD_LINK'])
      this.props.resetLoadingRedux(['GET_UPLOAD_LINK'])
    }
    if (uploadLink && uploadLink[this.zoomImgType]) {
      const imgUrl = uploadLink[this.zoomImgType].url
      if (this.zoomImgType === 'accessory') {
        this.zoomImgChange(
          {
            [`accessory_${this.zoomUploadIndex}`]: imgUrl,
          },
          this.zoomUploadIndex
        )
      } else {
        this.handleUpload(
          {
            [this.zoomImgType]: imgUrl,
          },
          this.zoomUploadIndex,
          this.zoomImgType
        )
      }
      resetPolicyStore(['uploadLink'])
      this.props.resetErrorRedux(['GET_UPLOAD_LINK'])
      this.props.resetLoadingRedux(['GET_UPLOAD_LINK'])
    }

    if (getUploadLinkError && uploadLinkStatus) {
      NotificationManager.error(uploadLinkStatus)
      resetPolicyStore(['uploadLinkStatus'])
    }
  }

  componentDidMount() {
    const [, dispatch] = this.context
    const { policyFormData } = this.props
    dispatch(
      saveCustomerData({
        customer_name: policyFormData?.customer_data?.name,
        mobile_no: policyFormData?.customer_data?.mobile_no,
        customer_address: policyFormData?.customer_data?.customer_address,
      })
    )
  }

  componentDidUpdate() {
    const { validateChassisNoStatus, validateChassisNoData, resetPolicyStore } = this.props
    if (validateChassisNoStatus === 'success') {
      this.setState((oldState) => ({
        isValidationChassisStart: validateChassisNoData.is_request_pending,
        showEditVehicleBtn: validateChassisNoData.is_request_pending
          ? false
          : oldState.showEditVehicleBtn,
      }))
      if (validateChassisNoData.is_request_pending) {
        // handle the recall for the chassis number validations
        this.checkTheNextCallTime(validateChassisNoData.data)
      } else {
        this.showEditChassisBtn()
      }
      resetPolicyStore(['validateChassisNoStatus'])
    } else if (validateChassisNoStatus) {
      resetPolicyStore(['validateChassisNoStatus'])
    }
  }

  checkTheNextCallTime = (data) => {
    const nextCallTimeMs = new Date(data.tentative_timestamp) - new Date(data.enquiry_timestamp)
    if (nextCallTimeMs > 20000) {
      this.clearChassisTimeOut = setTimeout(() => {
        this.handleValidateChassisNumber(this.tempChassisNumber)
      }, 20000)
    }
  }

  handleCloseEdit = () => {
    this.setState({
      showEditVehicleBtn: false,
    })
    this.handleOnChassisModal()
  }

  showEditChassisBtn = () => {
    this.chassisNumberError = false
    const { validateChassisNoData } = this.props
    this.setState({
      showEditVehicleBtn: !validateChassisNoData.success,
    })
  }

  handleCheckChassisValidations = async (e) => {
    // handle the chassis number validations accordingly
    const { validateChassisNoData } = this.props
    const formData = await this.handleSubmit(e, true)
    if (!formData) {
      NotificationManager.error(ERROR_LANG.pleaseProvideAllRequiredData)
      return
    }
    const { chasis_number: chassisNumber = {} } =
      validateChassisNoData.pre_validate_data_errors || {}
    if (chassisNumber.previous_end_date) {
      const currentDate = moment()
      const prevPolicyEndDate = moment(chassisNumber.previous_end_date)
      const startDate = moment(chassisNumber.start_date)
      const noOfDaysDiffCurrPrevDate = prevPolicyEndDate.diff(currentDate, 'days')
      if (noOfDaysDiffCurrPrevDate > 29) {
        // show error msg to agent
        this.setState({
          showChassisModal: {
            show: true,
            hideClose: true,
            okText: LANG_STRINGS.understand,
            content: LANG_STRINGS.chassisNumberPolicyAlreadyExist,
          },
        })
      } else {
        // handle case for start date and end date now
        if (startDate.isBefore(prevPolicyEndDate)) {
          // block user for the movements
          setToLocalStorage(VEHICLE_FORM_DATA, formData)
          this.setState({
            editChassisModal: {
              show: true,
              data: {
                ...chassisNumber,
                formData,
              },
            },
          })
        }
        // if start_date comes after the end date then its ok
      }
    }
  }

  handleSubmit = async (e, isDataReturn) => {
    if (this.chassisNumberError) {
      // handle show error here
      NotificationManager.error(LANG_STRINGS.chassisNumberPolicyAlreadyExist)
      return
    }
    const { packages = [] } = this.props
    const { images, errorImages, applicationData, isPhotoRequired } = this.state
    const oldCertificateUrl =
      applicationData.document_url || applicationData.old_policy_certificate_urls?.[0]?.url
    const pdfUploadUrl = get(applicationData, 'previous_certificate_url', '') || oldCertificateUrl
    let isCertificateError = false
    let finalData = {}
    let isError = false
    const response1 = await this.child.current.handleSubmit(e)

    const response2 = await this.customerDataFormSubmit.current(e)
    const respVehicleDamage = await this.vehicleDamageFormSubmitRef.current?.validateDamagePhoto(e)
    if (
      respVehicleDamage?.isDamaged &&
      (!respVehicleDamage.damage_photos || !respVehicleDamage.damage_remarks)
    ) {
      return
    } else if (respVehicleDamage?.isDamaged) {
      delete respVehicleDamage?.isDamaged
      delete respVehicleDamage?.errorField
    }
    let hardCopyData = {}
    if (applicationData.hard_copy_enabled) {
      hardCopyData = await HardCopySection.getHardCopyData(e)
    }

    let isValidHardCopy = true
    if (hardCopyData.hard_copy_required && !hardCopyData.isValid) {
      isValidHardCopy = false
    }

    if (
      isPhotoRequired &&
      (!images.dashboard || !images.front || !images.back || !images.left || !images.right)
    ) {
      isError = true
      this.setState({ errorImages: true })
      setTimeout(() => {
        if (isEmpty(getFromLocalStorageData(IS_SCROLL_START))) {
          smoothScroll('vehiclePhoto')
        }
      }, 100)
    } else if (isPhotoRequired) {
      isError = false
      this.setState({ errorImages: false })
    }

    let tempAccessoryError = false
    let accessories = []
    if (get(this.accessoriesRef, 'current.state.accessories', '')) {
      accessories = this.accessoriesRef.current.state.accessories
      accessories.forEach((accessory) => {
        if (!accessory.img && !tempAccessoryError) {
          tempAccessoryError = true
        }
      })
    }

    if (!isPhotoRequired && !pdfUploadUrl) {
      // here check the is certificate uploaded or not
      isCertificateError = true
      this.setState({
        certificateError: 'previous_certificate_url',
      })
    }
    this.setState({ errorAccessoryImages: tempAccessoryError })
    // there are error in the request body
    if (isPhotoRequired && isError) return
    if (this.isAppointmentLetter && !this.appointmentLetterUrl) {
      this.setState({
        appointmentLetterError: true,
      })
      return
    }

    let surveyData

    if (this.props.policyFormData?.provider_survey) {
      surveyData = await this.surveyDataFormSubmit.current(e)
      if (!surveyData) {
        return
      }
    }

    if (
      !isCertificateError &&
      response1 &&
      Object.keys(response1).length > 0 &&
      response2 &&
      Object.keys(response2).length > 0 &&
      !(isPhotoRequired && errorImages) &&
      !tempAccessoryError &&
      isValidHardCopy
    ) {
      const prevData = JSON.parse(JSON.stringify(this.props.policyFormData))
      const objMap = {}
      if (this.isAppointmentLetter && this.appointmentLetterUrl) {
        objMap.appointment_letter_url = this.appointmentLetterUrl
      }
      finalData = {
        ...prevData,
        ...response1,
        ...objMap,
        ...response2,
        ...respVehicleDamage,
        hard_copy_required: false,
        ...hardCopyData,
        usage: this.props.policyFormData.usage,
        accessories,
        ...(packages.length ? packages[0] : {}),
        stnk_url: get(response1, 'stnk_url.stnk_url', '') || get(response1, 'stnk_url', ''),
        previous_certificate_url: pdfUploadUrl,
        survey_response: surveyData,
      }
      if (isPhotoRequired) {
        finalData.images = images
      }
      delete finalData.brandList
      delete finalData.variantList
      delete finalData.variantPrice
      delete finalData.tnc
      delete finalData.benefit
      delete finalData.claims
      delete finalData.errorField
      delete finalData.premium_breakup
      delete finalData.package
      delete finalData.ktp
      if (isDataReturn) {
        return finalData
      }
      this.setState({ finalData })
      this.props.onSubmitForm(finalData)
    }
  }

  handleUpload = (value, index, type) => {
    if (type === 'ktp_url' || type === 'stnk_url' || type === 'previous_certificate_url') {
      this.setState((prevState) => {
        const applicationData = {
          ...prevState.applicationData,
          [type]: value && value[type],
        }
        return {
          applicationData,
        }
      })
      return
    }
    const { applicationData } = this.props
    const { images } = this.state
    Object.keys(value).forEach((key) => {
      if (value[key] && key.includes('image')) {
        const tempAccessoryData = applicationData.accessories
        tempAccessoryData[index] = { ...tempAccessoryData[index], img: value[key] }
        this.setState({ [applicationData.accessories]: tempAccessoryData })
      } else if (value[key]) {
        this.setState({ images: { ...images, ...value } })
      }
    })
  }

  handleUploadFromDisk = (e, inputName) => {
    // e.preventDefault()
    // inputName passed by the zoom modal input change method
    const { getUploadLink } = this.props
    const file = document.getElementById(inputName)
    if ('files' in file) {
      if (file.files[0]) {
        if (file.files[0].size > 11000000) {
          NotificationManager.error('Ukuran file terlalu besar')
        } else {
          NotificationManager.info('Pengunggahan dimulai')
          getUploadLink({ file: file.files[0], name: this.zoomImgType })
          this.setState({
            showZoomModal: false,
          })
        }
      }
    }
  }

  handleOpenImgModal = (title, containerType) => {
    let imgContainer = ''
    let modalTitle = ''
    let btmTitle = ''

    switch (containerType) {
      case 'stnk_url':
        modalTitle = LANG_STRINGS.stnkPhotoGuide
        btmTitle = LANG_STRINGS.makeSureVehicleRegistrationPicClear
        imgContainer = (
          <SingleImgContainer
            title={LANG_STRINGS.stnkPhoto}
            imgUrl={STNK}
            titlePosition="up"
            titleAlign="start"
          />
        )
        break
      case 'ktp_url':
        modalTitle = LANG_STRINGS.ktpPhotoGuide
        btmTitle = LANG_STRINGS.makeSureKTPPhotoClear
        imgContainer = (
          <SingleImgContainer
            title={LANG_STRINGS.photoKTP}
            imgUrl={KTP_IMG}
            titlePosition="up"
            titleAlign="start"
          />
        )
        break
      case 'vehicle_photo':
        modalTitle = LANG_STRINGS.vehiclePhotoGuide
        btmTitle = LANG_STRINGS.makeSureCarPicClear
        imgContainer = this.getVehicleImgContainer()
        break
      case 'previous_certificate_url':
        modalTitle = LANG_STRINGS.certificatePolicyGuide
        btmTitle = LANG_STRINGS.verifyThePolicyCertificate
        imgContainer = (
          <SingleImgContainer
            title={LANG_STRINGS.policyCertificate}
            imgUrl={CERTIFICATE_PREVIEW}
            titlePosition="up"
            titleAlign="start"
            height="300px"
          />
        )
        break
      default:
        break
    }

    this.setState((prevState) => ({
      showImgModal: !prevState.showImgModal,
      modalImgContainer: imgContainer,
      modalTitle: modalTitle,
      modalBottomTitle: btmTitle,
    }))
  }

  handleCloseImgModal = () => {
    this.setState({
      showImgModal: false,
      modalImgContainer: '',
      modalTitle: '',
    })
  }

  handleToggleZoomModal = (data = {}) => {
    this.setState((prevState) => ({
      showZoomModal: !prevState.showZoomModal,
      zoomImgUrl: data.imgUrl,
      zoomTitle: data.title,
    }))
    if (data.type) {
      this.zoomImgChange = data.onImgChange
      this.zoomUploadIndex = data.index
      this.zoomImgType = data.type
    }
    this.zoomRemoveImg = data.onRemove
  }

  handleAppointmentCheckbox = (checked) => {
    this.isAppointmentLetter = checked
  }

  handleAppointmentLetter = (url) => {
    this.appointmentLetterUrl = url
  }

  handleRemoveImg = () => {
    // here handle the remove of the selected image
    if (this.zoomImgType === 'accessory') {
      // Handling of accessory remove from the updated accessory
      // this function attached by the accessory component
      this.zoomRemoveImg({
        index: this.zoomUploadIndex,
        type: this.zoomImgType,
      })
      this.handleToggleZoomModal({})
      return
    }
    const { images } = this.state
    images[this.zoomImgType] = ''
    this.setState({
      images,
    })
    this.handleToggleZoomModal({})
  }

  getVehicleImgContainer = () => {
    return (
      <VehicleImgGuideStyle>
        <SingleImgContainer
          title={LANG_STRINGS.dashboard}
          imgUrl={VEHICLE_DASHBOARD_IMG}
          titleAlign="center"
        />
        <Row align="center" justify="space-between">
          <SingleImgContainer
            title={LANG_STRINGS.frontLook}
            imgUrl={VEHICLE_FACE_IMG}
            titleAlign="center"
          />
          <SingleImgContainer
            title={LANG_STRINGS.back}
            imgUrl={VEHICLE_BACK_IMG}
            titleAlign="center"
          />
        </Row>
        <Row align="center" justify="space-between">
          <SingleImgContainer
            title={LANG_STRINGS.toTheRightSide}
            imgUrl={VEHICLE_RIGHT_FACE_IMG}
            titleAlign="center"
          />
          <SingleImgContainer
            title={LANG_STRINGS.leftSide}
            imgUrl={VEHICLE_LEFT_FACE_IMG}
            titleAlign="center"
          />
        </Row>
      </VehicleImgGuideStyle>
    )
  }

  getGuideContainer = (title, type) => {
    return (
      <Row align="center" onClick={() => this.handleOpenImgModal(title, type)}>
        <CustomText color={AgentColorPallette.darkerGold} weight={700}>
          {LANG_STRINGS.guide}
        </CustomText>
        &nbsp;&nbsp;
        <img src={LIGHT_GOLD_BULB} alt="" />
      </Row>
    )
  }

  getHeadingContainer = (title, errorAccessoryImages, bottom) => {
    return (
      <>
        <Row justify="space-between" align="center">
          <CustomText color={AgentColorPallette.black} size="16px" weight={800} bottom={bottom}>
            {title}
          </CustomText>
          {errorAccessoryImages && (
            <CustomText color={AgentColorPallette.errorDark}>{'Wajib Diisi'}</CustomText>
          )}
        </Row>
      </>
    )
  }

  getErrorContainer = (title, error) => {
    return (
      <CustomText
        color={error ? AgentColorPallette.errorDark : AgentColorPallette.fontGrey}
        marginBottom="14px"
      >
        {title}
      </CustomText>
    )
  }

  getTitleAndGuide = (title, type) => {
    return (
      <Row align="center" justify="space-between">
        <CustomText
          size="12px"
          color={AgentColorPallette.fontSecondary}
          top="4px"
          bottom="4px"
          textAlign="start"
        >
          {title}
        </CustomText>
        {this.getGuideContainer(LANG_STRINGS.stnkPhotoGuide, type)}
      </Row>
    )
  }

  getVehiclePhotoContainer = (images = {}, imageUploadError, errorImages, isPhotoRequired) => (
    <>
      <hr />
      {
        <Row align="center" justify="space-between" id="vehiclePhoto">
          {this.getHeadingContainer(`2. ${LANG_STRINGS.vehiclePhoto}`, errorImages, '1px')}
          {this.getGuideContainer(LANG_STRINGS.vehiclePhotoGuide, 'vehicle_photo')}
        </Row>
      }
      {this.getErrorContainer(LANG_STRINGS.useThePersonalPhotos, imageUploadError)}
      {this.getRowImageContainer(
        LANG_STRINGS.dashboard,
        images.dashboard,
        'dashboard',
        errorImages
      )}
      <div className="photos-container">
        {this.getRowImageContainer(
          LANG_STRINGS.frontLook,
          images.front,
          'front',
          errorImages,
          '44%'
        )}
        {this.getRowImageContainer(LANG_STRINGS.backView, images.back, 'back', errorImages, '44%')}
      </div>
      <div className="photos-container">
        {this.getRowImageContainer(LANG_STRINGS.leftSide, images.left, 'left', errorImages, '44%')}
        {this.getRowImageContainer(
          LANG_STRINGS.toTheRightSide,
          images.right,
          'right',
          errorImages,
          '44%'
        )}
      </div>
    </>
  )

  getCertificateUpload = () => {
    const { applicationData = {} } = this.state
    const oldCertificateUrl =
      applicationData.document_url || applicationData.old_policy_certificate_urls?.[0]?.url
    return (
      <>
        <hr />
        <Row align="center" justify="space-between">
          {this.getHeadingContainer(`3. ${LANG_STRINGS.policyCertificate}`, '', '12px')}
        </Row>
        {this.getTitleAndGuide(LANG_STRINGS.policyPhotoCertificate, 'previous_certificate_url')}
        <Upload
          label={LANG_STRINGS.policyPhotoCertificate}
          onUpload={(value, index) => this.handleUpload(value, index, 'previous_certificate_url')}
          name="previous_certificate_url"
          fileType={`${INPUT_FILE_TYPE.IMAGE},${INPUT_FILE_TYPE.PDF}`}
          hideLabel
          showImg
          icon={DOCUMENT}
          hideUpload={this.props.isRenewalFlow}
          errorField={
            this.state.certificateError &&
            !applicationData.previous_certificate_url &&
            'previous_certificate_url'
          }
          defaultValue={applicationData.previous_certificate_url || oldCertificateUrl}
        />
      </>
    )
  }

  getPdfUploadContainer = (img, title, type, hideUploadLabel, errorImages) => {
    // this is function handling the pdf container
    return (
      <Upload
        label={title}
        onUpload={(value, index) => this.handleUpload(value, index, type)}
        width="100%"
        name={type}
        fileType={`${INPUT_FILE_TYPE.IMAGE},${INPUT_FILE_TYPE.PDF}`}
        hideLabel={hideUploadLabel}
        icon={DOCUMENT}
        errorField={errorImages && !img && type}
      />
    )
  }

  getImageTitleContainer = (title, imgUrl, width, invert, type) => {
    return (
      <div>
        {invert && this.getTitleAndGuide(title, type)}
        <div
          className={`image-display ${width && 'small-img-container'}`}
          style={{
            backgroundImage: `url(${imgUrl})`,
            marginBottom: 8,
            width: width || '100%',
          }}
          onClick={() =>
            this.handleToggleZoomModal({
              imgUrl,
              title,
              type,
            })
          }
        >
          <div className="zoom-img">
            <img src={SEARCH} width="9px" alt="zoom" />
          </div>
        </div>
        {!invert && (
          <CustomText
            size="12px"
            color={AgentColorPallette.fontSecondary}
            top="4px"
            bottom="20px"
            textAlign="center"
          >
            {title}
            <RequiredStar>*</RequiredStar>
          </CustomText>
        )}
      </div>
    )
  }

  getRowImageContainer = (
    title,
    img,
    type,
    errorImages,
    width,
    labelAlign,
    invert = false,
    hideUploadLabel = false
  ) => {
    return img ? (
      this.getImageTitleContainer(title, img, width, invert, type)
    ) : (
      <>
        {invert && this.getTitleAndGuide(title, type)}
        <Upload
          label={title}
          onUpload={(value, index) => this.handleUpload(value, index, type)}
          width={width || '100%'}
          name={type}
          labelAlign={labelAlign}
          hideLabel={hideUploadLabel}
          required
          errorField={errorImages && !img && type}
        />
      </>
    )
  }

  handleCustomerAddressChange = (customerAddress) => {
    const [, dispatch] = this.context
    dispatch(
      saveCustomerData({
        customer_address: customerAddress,
      })
    )
  }

  handleCustomerFormChange = (value, name) => {
    const [, dispatch] = this.context
    const key = name === 'name' ? 'customer_name' : name
    dispatch(
      saveCustomerData({
        [key]: value,
      })
    )
  }

  onHandleGetSubmitMethods = (formType, method) => {
    switch (formType) {
      case 'customer-data-form':
        this.customerDataFormSubmit.current = method
        break
      case 'survey-data-form':
        this.surveyDataFormSubmit.current = method
        break
      default:
        break
    }
  }

  handleValidateChassisNumber = (number) => {
    if (this.clearChassisTimeOut && number !== this.tempChassisNumber) {
      // clear the time out if any interval is pending if new chassis number entered
      clearTimeout(this.clearChassisTimeOut)
    }
    const { applicationData } = this.state
    if (!isEmpty(applicationData.pre_validate_params)) {
      this.tempChassisNumber = number
      this.props.validateChassisNumber({
        body: {
          code: applicationData.code,
          pre_validate_data: {
            chasis_number: {
              chasis_number: number,
              start_date: applicationData.start_date,
            },
          },
        },
      })
    }
  }

  handleOnChassisModal = () => {
    // scroll to chassis number input
    this.handleCloseChassisModal()
    smoothScroll('chasis_number_div')
    this.chassisNumberError = true
    this.child.current.setState((prevState) => {
      return {
        errorField: {
          ...prevState.errorField,
          chasis_number: LANG_STRINGS.chassisNumberPolicyAlreadyExist,
        },
      }
    })
  }

  handleCloseChassisModal = () => {
    this.setState({
      showChassisModal: {},
    })
  }

  handleCloseEditChassis = () => {
    // handle close edit modal
    this.setState({
      editChassisModal: {
        show: false,
      },
    })
  }

  render() {
    const localData = getFromLocalStorageData(AGENT_MV_FORM_DATA)
    const { stepTitle, stepCurrent, stepTotal, isRenewalFlow, validatingChassisLoading } =
      this.props
    let { policyFormData = {} } = this.props
    if (!isEmpty(localData) && !policyFormData.color) {
      policyFormData = localData
    }

    const {
      applicationData,
      images,
      errorImages,
      modalTitle,
      modalImgUrl,
      modalBottomTitle,
      errorAccessoryImages,
      imageUploadError,
      showImgModal,
      modalImgContainer,
      isPhotoRequired,
      editChassisModal,
      isValidationChassisStart,
      showZoomModal,
      zoomTitle,
      zoomName,
      zoomImgUrl,
      appointmentLetterError,
      showChassisModal,
    } = this.state
    const isChassisValidation = validatingChassisLoading || isValidationChassisStart
    const applicationDate = get(policyFormData, 'application_date', '')
    const { proposed_admin_fee: proposedAdminFee } = policyFormData

    const checkDate = moment('2021-04-22', 'YYYY-MM-DD')
    const isOldQuotation = moment(applicationDate, 'YYYY-MM-DD').isBefore(checkDate)

    const {
      accessories = [],
      // stnk_url: stnkUrl,
      hard_copy_enabled: hardCopyEnabled = false,
      purchase_type: purchaseType,
      appointment_letter_url: appointmentLetterUrl,
    } = applicationData
    let alwaysChargeHardCopy = false
    if (isRenewalFlow) {
      alwaysChargeHardCopy = applicationData?.product?.always_charge_hard_copy
    } else {
      alwaysChargeHardCopy = applicationData?.always_charge_hard_copy
    }
    const modifyPolicyFormData = getPolicyFormData(policyFormData, isRenewalFlow)
    const isRenewalOther = purchaseType === 'renew-from-other'

    return (
      <PolicyCustAgentFormStyle>
        <StepsHeader
          className="steps-header-custom"
          leftText={stepTitle}
          current={stepCurrent}
          totalSteps={stepTotal}
        />
        <div className="form-container">
          {this.getHeadingContainer(`1. ${LANG_STRINGS.vehicleData}`, false, '14px')}
          <InnerForm
            formData={modifyPolicyFormData}
            ref={this.child}
            onValidateChassisNumber={this.handleValidateChassisNumber}
            onGuideClick={() => this.handleOpenImgModal(LANG_STRINGS.stnkPhoto, 'stnk_url')}
          />
          {isPhotoRequired &&
            this.getVehiclePhotoContainer(images, imageUploadError, errorImages, isPhotoRequired)}
          {!!(accessories.length > 0) && (
            <>
              <hr />
              {this.getHeadingContainer(
                `${isPhotoRequired ? '3.' : '2.'} ${LANG_STRINGS.additionalAccessories}`,
                errorAccessoryImages,
                '1px'
              )}
              {this.getErrorContainer(LANG_STRINGS.useThePersonalPhotos, imageUploadError)}
            </>
          )}
          {!!accessories.length && (
            <AccessoriesWithImage
              accessories={accessories}
              errorAccessoryImages={errorAccessoryImages}
              ref={this.accessoriesRef}
              onZoomImg={this.handleToggleZoomModal}
            />
          )}
          <hr />
          <CustomerDataForm
            title={`${accessories.length > 0 ? '4. ' : '3. '} ${LANG_STRINGS.customerData}`}
            preFormData={policyFormData}
            handleGetSubmitMethods={this.onHandleGetSubmitMethods}
            onGuideClick={() => this.handleOpenImgModal(LANG_STRINGS.photoKTP, 'ktp_url')}
            onCustomerAddressChange={this.handleCustomerAddressChange}
            onCustomerFormChange={this.handleCustomerFormChange}
            isOldQuotation={isOldQuotation}
            isRenewalFlow={isRenewalFlow}
          />
          {!isPhotoRequired && this.getCertificateUpload()}
          {isRenewalOther && (
            <>
              <hr />
              <AppointmentLetter
                appointmentLetterUrl={appointmentLetterUrl}
                error={appointmentLetterError}
                onUploadAppointmentLetter={this.handleAppointmentLetter}
                onCheckboxSelect={this.handleAppointmentCheckbox}
              />
            </>
          )}
          {
            <VehicleDamagePhotos
              ref={this.vehicleDamageFormSubmitRef}
              damageData={{
                damage_remarks: policyFormData.damage_remarks,
                damage_photos: policyFormData.damage_photos,
              }}
            />
          }
          {hardCopyEnabled && (
            <HardCopySection
              isHideSendToPP={
                isObject(policyFormData?.provider_branch)
                  ? !policyFormData?.provider_branch?.tags?.includes('HEADQUARTER')
                  : false
              }
              isCustomerForm={this.isCustomerForm}
              preFilledData={{
                hard_copy_required: policyFormData?.hard_copy_required,
                hard_copy_sent_to: policyFormData?.hard_copy_sent_to,
                customer_address: policyFormData?.customer_data?.customer_address,
                customer_name: policyFormData?.customer_data?.name,
                mobile_no: policyFormData?.customer_data?.mobile_no,
                hard_copy_address: policyFormData?.hard_copy_address,
                hard_copy_recipient:
                  policyFormData?.hard_copy_recipient ||
                  (policyFormData.hard_copy_sent_to === SEND_TO_CUSTOMER
                    ? policyFormData?.customer_data?.name
                    : ''),
                hard_copy_recipient_mobile:
                  policyFormData?.hard_copy_recipient_mobile ||
                  (policyFormData.hard_copy_sent_to === SEND_TO_CUSTOMER
                    ? policyFormData?.customer_data?.mobile_no
                    : ''),
              }}
              proposedAdminFee={proposedAdminFee}
              isHardCopyRequired={alwaysChargeHardCopy}
            />
          )}
          {policyFormData?.provider_survey && (
            <>
              <hr />
              <SurveySection
                handleGetSubmitMethods={this.onHandleGetSubmitMethods}
                preFormData={policyFormData}
              />
            </>
          )}
        </div>
        <div className="footer">
          <div className="footer-padding">
            {this.state.showEditVehicleBtn ? (
              <>
                <CustomText color={AgentColorPallette.blood} bottom="10px" textAlign="center">
                  {LANG_STRINGS.chassisNumberPolicyAlreadyExist}
                </CustomText>
                <Row justify="space-between">
                  <Button
                    backgroundColor={AgentColorPallette.blue}
                    color={AgentColorPallette.white}
                    onClick={this.handleCloseEdit}
                    width="45%"
                  >
                    {LANG_STRINGS.cancel}
                  </Button>
                  <Button width="45%" onClick={this.handleCheckChassisValidations}>
                    {LANG_STRINGS.change}
                  </Button>
                </Row>
              </>
            ) : (
              <Button
                className="submit-button"
                onClick={isChassisValidation ? () => {} : this.handleSubmit}
                id="mobilPolicyFormAgentStep_3-next"
              >
                {isChassisValidation ? LANG_STRINGS.validatingVehicleData : LANG_STRINGS.next}
              </Button>
            )}
          </div>
        </div>
        <ImageGuideModal
          showImgModal={showImgModal}
          title={modalTitle}
          onClose={this.handleCloseImgModal}
          imgUrl={modalImgUrl}
          modalImgContainer={modalImgContainer}
          bottomTitle={modalBottomTitle}
        />
        {showZoomModal && (
          <ZoomEditImg
            showModal={showZoomModal}
            title={zoomTitle}
            imgUrl={zoomImgUrl}
            name={zoomName}
            onClose={this.handleToggleZoomModal}
            onChangeImg={this.handleUploadFromDisk}
            onRemoveImg={this.handleRemoveImg}
          />
        )}
        {showChassisModal.show && (
          <WarningModal
            hideIcon
            showModal={showChassisModal.show}
            warning={showChassisModal.content}
            onOk={this.handleOnChassisModal}
            hideCloseBtn={showChassisModal.hideClose}
            okText={showChassisModal.okText}
            onClose={this.handleCloseChassisModal}
          />
        )}
        {editChassisModal.show && (
          <VehicleChassisEdit
            applicationData={applicationData}
            data={editChassisModal.data}
            showModal={editChassisModal.show}
            onClose={this.handleCloseEditChassis}
            onValidation={this.props.onSubmitForm}
          />
        )}
      </PolicyCustAgentFormStyle>
    )
  }
}

PolicyCustAgentForm.contextType = GlobalContext

export default connect(
  (state) => ({
    getUploadLinkLoading: state.Loading.GET_UPLOAD_LINK,
    validatingChassisLoading: state.Loading.VALIDATE_CHASSIS_NO,
    uploadLink: state.Policy.uploadLink,
    getUploadLinkError: state.Error.GET_UPLOAD_LINK,
    propertyCities: state.Property.propertyCities,
    provinces: state.Property.provinces,
    agentDetails: state.User.agentDetails,
    validateChassisNoData: state.Policy.validateChassisNoData,
    validateChassisNoStatus: state.Policy.validateChassisNoStatus,
    isStaffAgent: state.User.isStaffAgent,
  }),
  {
    getUploadLink,
    resetPolicyStore,
    resetLoadingRedux,
    validateChassisNumber,
    resetErrorRedux,
  }
)(PolicyCustAgentForm)
