import moment from 'moment'
import { useState, useCallback, useRef, useEffect } from 'react'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../lang/index'
import { VehicleChassisEditStyle } from './index.style'
import TitleError from '../../../../TitleError'
import { Button, InnerInput } from '../../../..'
import DobInput from '../../../../DobInput'
import { useHistory } from 'react-router-dom'
import { typeValid } from '../../../../../helpers/validations'
import { useValidateChassisNumber } from '../../../../../state/commonState/hooks/useCommonContext'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import Loader from '../../../../Loader'
import ShowSnackbar from '../../../../ShowNotification'
import { getFromLocalStorageData, removeFromLocalStorageData, setToLocalStorage } from '../../../../../helpers/localstorage'
import { POLICY_PKG_DATA, STEPS_DATA, VEHICLE_FORM_DATA } from '../../../../../constants/cookies'

function VehicleChassisEditContainer ({ data, onClose, applicationData, draftId, onValidation = () => {} }) {
  const [state, setState] = useState({
    isShowStartDate: moment(data.previous_end_date).isBefore(moment().add(31, 'days'))
  })
  const [disabledBtn, setDisabledBtn] = useState(true)
  // get the form data from here and submit the call and show the update items
  const formData = useRef(data.formData || getFromLocalStorageData(VEHICLE_FORM_DATA))
  const that = useRef({
    isPrevEndDateIn30Day: moment(data.previous_end_date).isBefore(moment().add(31, 'days')),
    startDate: moment(data.start_date).format('DD/MM/YYYY'),
    isStartDateValid: false,
    apiCount: 3,
    clearChassisTimeOut: '',
    chassisNumber: data.chasis_number
  })
  const dateRef = useRef()
  const history = useHistory()
  const [{ VALIDATE_CHASSIS_NO_LOADER }] = useLoaderContextValue()
  const [{ validateChassisNoStatus }] = useErrorContextValue()
  const [{ validateChassisNoData = {} }, validateChassisNoReq] = useValidateChassisNumber()
  const { resetError } = useResetError()

  const validateChassis = useCallback(() => {
    validateChassisNoReq({
      body: {
        code: applicationData.code,
        pre_validate_data: {
          chasis_number: {
            chasis_number: that.current.chassisNumber,
            start_date: moment(that.current.startDate, 'DD/MM/YYYY').format('YYYY-MM-DD')
          }
        }
      }
    })
  }, [validateChassisNoReq, applicationData])

  useEffect(() => {
    // validate chassis number
    if (validateChassisNoStatus === 'success') {
      // check is data is ok if not then show error
      if (!validateChassisNoData.success) {
        setState(oldState => {
          return {
            ...oldState,
            errorChassis: 'chasis_number'
          }
        })
      } else if (validateChassisNoData.is_request_pending) {
        that.current.clearChassisTimeOut = setTimeout(() => {
          validateChassis()
        }, 20000)
      } else {
        // handle the form data here
        // with new chassis number
        onValidation({
          ...formData.current,
          chasis_number: that.current.chassisNumber,
          start_date: moment(that.current.startDate, 'DD/MM/YYYY').format('YYYY-MM-DD')
        })
        onClose()
      }
      resetError(['validateChassisNoStatus'])
    } else if (validateChassisNoStatus) {
      if (!that.current.apiCount) {
        ShowSnackbar.error({
          visible: true,
          text: validateChassisNoStatus
        })
      } else {
        that.current.apiCount -= 1
        validateChassis()
      }
      resetError(['validateChassisNoStatus'])
    }
  }, [
    resetError, onValidation, validateChassis, onClose,
    validateChassisNoStatus, validateChassisNoData
  ])

  const handleChassisNumber = useCallback((e) => {
    if (that.current.clearChassisTimeOut && (e.target.value !== that.current.chassisNumber)) {
      // clear the time out if any interval is pending if new chassis number entered
      clearTimeout(this.clearChassisTimeOut)
    }
    that.current.chassisNumber = e.target.value
    setDisabledBtn(that.current.chassisNumber === data.chasis_number)
    setState(oldState => {
      return {
        ...oldState,
        isShowStartDate: (that.current.chassisNumber !== data.chasis_number),
        errorChassis: state.errorChassis ? '' : state.errorChassis
      }
    })
  }, [state, data])

  const handleDobChange = useCallback((date) => {
    that.current.startDate = date
    if (state.errorDob) {
      setState(oldState => {
        return {
          ...oldState,
          errorStartDateText: '',
          errorDob: ''
        }
      })
    }
  }, [state])

  const getMinimumEndDate = useCallback(() => {
    if ((that.current.chassisNumber === data.chasis_number) && that.current.isPrevEndDateIn30Day) {
      return new Date(data.previous_end_date)
    }
    return new Date()
  }, [data])

  const getMaximumDate = useCallback(() => {
    return moment(Date.now()).add((30), 'day')._d
  }, [])

  const getDefaultStartDate = useCallback(() => {
    // that.current.chassisNumber, data.chasis_number
    if ((that.current.chassisNumber === data.chasis_number) && that.current.isPrevEndDateIn30Day) {
      return moment(data.previous_end_date).format('DD/MM/YYYY')
    }
    return moment().format('DD/MM/YYYY')
  }, [data])

  const handleSubmit = useCallback(() => {
    if (dateRef.current && dateRef.current.state.showError) {
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.invalidDateFormat
      })
      return
    }
    if (!that.current.startDate) {
      ShowSnackbar.error({
        visible: true,
        text: LANG_STRINGS.required
      })
      return
    }
    // here we are checking the new start Date year
    // if year gets change then we are redirecting to new user details
    const currentYear = new Date().getFullYear()
    const startDateYear = parseInt(that.current.startDate.split('/')[2], 10)
    const isSameChassisNo = that.current.chassisNumber === data.chasis_number
    if (startDateYear !== currentYear) {
      // redirect the user package details page
      setToLocalStorage(POLICY_PKG_DATA, {
        applicationData: {
          ...applicationData,
          ...formData.current,
          chasis_number: that.current.chassisNumber,
          start_date: moment(that.current.startDate, 'DD/MM/YYYY').format('YYYY-MM-DD')
        },
        package_code: applicationData.code,
        purchaseType: applicationData.purchase_type,
        selectedAddon: applicationData.addons
      })
      setToLocalStorage(STEPS_DATA, 3)
      removeFromLocalStorageData(VEHICLE_FORM_DATA)
      if (draftId) {
        onValidation({
          ...formData.current,
          chasis_number: that.current.chassisNumber,
          start_date: moment(that.current.startDate, 'DD/MM/YYYY').format('YYYY-MM-DD')
        }, true)
        // history.push(`/motor_vehicle/packages/details/v2/${draftId}`)
      } else {
        history.push('/motor_vehicle/packages/details')
      }
    } else if (isSameChassisNo && that.current.isPrevEndDateIn30Day) {
      // show error and ask to change the start date between prev_policy_end_date and current_end_date
      setState(oldState => {
        return {
          ...oldState,
          errorStartDateText: `Silakan masukkan tanggal di antara ${moment(data.previous_end_date).format('DD/MM/YYYY')} hingga ${moment(Date.now()).add((30), 'day').format('DD/MM/YYYY')} `,
          errorDob: 'start_date'
        }
      })
    } else {
      // handle happy flow
      if (typeValid('chasis_number', that.current.chassisNumber)) {
        // if valid then call validations api
        validateChassis()
      } else {
        setState(oldState => {
          return {
            ...oldState,
            chassisErrorText: 'Format Tidak Valid',
            errorChassis: 'chasis_number'
          }
        })
      }
    }
  }, [
    history, validateChassis, applicationData,
    data, draftId, onValidation])

  return (
    <Loader visible={VALIDATE_CHASSIS_NO_LOADER || validateChassisNoData.is_request_pending}>
      <VehicleChassisEditStyle>
        <TitleError
          title={LANG_STRINGS.activePolicyEndDate}
        />
        <div className='disabled-text'>
          {moment(data.previous_end_date).format('DD/MM/YYYY')}
        </div>
        <TitleError
          title={LANG_STRINGS.chassisNumber}
          error={state.errorChassis && (state.chassisErrorText || LANG_STRINGS.chassisNumberPolicyAlreadyExist)}
        />
        <InnerInput
          name='chasis_number'
          errorField={state.errorChassis}
          placeholder={LANG_STRINGS.chassisNumber}
          onChange={handleChassisNumber}
          defaultValue={data.chasis_number}
          displayBorder
        />
        {
          state.isShowStartDate && (
            <>
              <TitleError
                title={LANG_STRINGS.policyStartPeriod}
                error={state.errorStartDateText}
              />
              <DobInput
                errorField={state.errorDob}
                name='start_date'
                onDobSelect={handleDobChange}
                minDate={getMinimumEndDate()}
                ref={dateRef}
                defaultValue={getDefaultStartDate()}
                maxDate={getMaximumDate()}
              />
              <div className='user-note'>
                <b>{LANG_STRINGS.note}: </b>{LANG_STRINGS.policyDateChangeNote}
              </div>
            </>
          )
        }
        <div className='bottom-btn'>
          <Button
            onClick={handleSubmit}
            disabled={disabledBtn}
          >
            {LANG_STRINGS.continue}
          </Button>
        </div>
        <ShowSnackbar hideOkay />
      </VehicleChassisEditStyle>
    </Loader>
  )
}

export default VehicleChassisEditContainer
