import { useCallback, useRef, useState } from 'react'
import { Upload } from '../../..'
import { Row } from '../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { DOCUMENT, LIGHT_GOLD_BULB } from '../../../../images'
import { LANG_STRINGS } from '../../../../lang'
import CustomCheckbox from '../../../CustomCheckbox'
import CustomText from '../../../CustomText'
import ToolTip from '../../../ToolTip'
import { AppointmentLetterStyle } from './index.style'
import { INPUT_FILE_TYPE } from '../../../../constants/file'

function AppointmentLetter(props) {
  const {
    error,
    onUploadAppointmentLetter = () => {},
    onCheckboxSelect = () => {},
    appointmentLetterUrl,
  } = props
  const [isAppointmentLetter, setAppointmentLetter] = useState(!!appointmentLetterUrl)

  const tooltipRef = useRef()

  const handleCheckbox = useCallback(() => {
    setAppointmentLetter((isAppointmentLetter) => {
      const checked = !isAppointmentLetter
      onCheckboxSelect(checked)
      return checked
    })
  }, [onCheckboxSelect])

  const handleUpload = useCallback(
    (value = {}) => {
      onCheckboxSelect(true)
      onUploadAppointmentLetter(value.appointment_letter_url)
    },
    [onUploadAppointmentLetter, onCheckboxSelect]
  )

  const handleHideToolTip = () => {
    if (tooltipRef.current) {
      tooltipRef.current.handleCloseTip()
    }
  }

  return (
    <AppointmentLetterStyle>
      <CustomText color={AgentColorPallette.black} size="16px" weight={800} bottom="12px">
        {LANG_STRINGS.otherDocuments}
      </CustomText>
      <Row justify="space-between">
        <CustomCheckbox
          isChecked={isAppointmentLetter}
          onChange={handleCheckbox}
          name="appointmentLetter"
          id="appointmentLetter"
          color={AgentColorPallette.black}
        />
        <div>
          <CustomText color={AgentColorPallette.darkCharcoal} weight={700}>
            {LANG_STRINGS.uploadAppointmentLetter}
          </CustomText>
          <CustomText color={AgentColorPallette.fontDarkerGrey} size="10px">
            {LANG_STRINGS.documentMustSignedByInsured}
          </CustomText>
        </div>
      </Row>
      {isAppointmentLetter && (
        <>
          <Row justify="space-between" align="center" className="appointment-label">
            <CustomText color={AgentColorPallette.fontDarkerGrey}>
              {LANG_STRINGS.letterOfAppointment}
            </CustomText>
            <ToolTip
              ref={tooltipRef}
              dataView={
                <div className="appointment-guide-content">
                  <CustomText weight={700} size="14px">
                    {LANG_STRINGS.uploadGuide}
                  </CustomText>
                  <CustomText>{LANG_STRINGS.makeSureThePhotoYouUploadClear}</CustomText>
                  <Row justify="flex-end">
                    <CustomText
                      className="appointment-btn"
                      color={AgentColorPallette.aqua}
                      size="14px"
                      top="10px"
                      weight={800}
                      onClick={handleHideToolTip}
                    >
                      {LANG_STRINGS.understand}
                    </CustomText>
                  </Row>
                </div>
              }
              className="appointment-letter-guide"
            >
              <Row align="center">
                <CustomText color={AgentColorPallette.darkerGold} weight={700}>
                  {LANG_STRINGS.guide}
                </CustomText>
                &nbsp;&nbsp;
                <img src={LIGHT_GOLD_BULB} alt="" />
              </Row>
            </ToolTip>
          </Row>
          <Upload
            label={LANG_STRINGS.letterOfAppointment}
            onUpload={(value, index) => handleUpload(value, index)}
            name="appointment_letter_url"
            fileType={`${INPUT_FILE_TYPE.IMAGE},${INPUT_FILE_TYPE.PDF}`}
            height="145px"
            hideLabel
            icon={DOCUMENT}
            showImg
            defaultValue={appointmentLetterUrl}
            errorField={error && 'appointment_letter_url'}
          />
          <CustomText size="10px" color={AgentColorPallette.fontDarkerGrey}>
            {LANG_STRINGS.fileType}
          </CustomText>
        </>
      )}
    </AppointmentLetterStyle>
  )
}

export default AppointmentLetter
