import { InfoModalStyle } from './index.style'
import ReactModal from 'react-responsive-modal'

const modalStyle = {
  modal: {
    padding: 0,
    width: '100%',
    minWidth: '250px',
    maxWidth: '350px',
    borderRadius: '24px'
  },
  overlay: {
    padding: 0,
    width: '100%'
  }
}

function InfoModal (props) {
  const { showModal, onCloseModal, children } = props

  return (
    <ReactModal
      open={showModal}
      styles={modalStyle}
      onClose={onCloseModal}
      center
      showCloseIcon={false}
      focusTrapped={false}
    >
      <InfoModalStyle>
        {children}
      </InfoModalStyle>
    </ReactModal>
  )
}

export default InfoModal
