import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { isEmpty } from 'lodash'
import moment from 'moment'
import { useCallback, useEffect, useRef, useState } from 'react'
import { CustomText } from '../..'
import { Row } from '../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../lang'
import { useGetSurveyForm } from '../../../state/commonState/hooks/useCommonContext'
import AddressForm from '../../AddressForm'
import ShowSnackbar from '../../ShowNotification'
import Switch from '../../Switch'
import VerticalRadioGroup from '../../VerticalRadioGroup'
import { SurveySectionStyle } from './index.style'

function SurveySection (props) {
  const isInitialRender = useRef(true)
  const { handleGetSubmitMethods, preFormData } = props
  const [answers, setAnswers] = useState({})
  const addressMethodsObj = useRef({})

  const [{ getSurveyFormStatus, GET_SURVEY_FORM_ERROR }, dispatchError] = useErrorContextValue()
  const [{ getSurveyFormData = [] }, getSurveyFormRequest] = useGetSurveyForm()

  useEffect(() => {
    if (GET_SURVEY_FORM_ERROR && getSurveyFormStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getSurveyFormStatus
      })
      dispatchError(resetError({
        getSurveyFormStatus: ''
      }))
    }
  }, [
    getSurveyFormStatus, GET_SURVEY_FORM_ERROR, dispatchError
  ])

  useEffect(() => {
    if (isInitialRender.current) {
      getSurveyFormRequest({
        query: {
          provider_code: preFormData?.provider?.code,
          policy_start_date: preFormData?.start_date
        }
      })
      isInitialRender.current = false
    }
  }, [preFormData, getSurveyFormRequest])

  const handleAnsChange = useCallback((id, val, type, isRequired = false) => {
    setAnswers({
      ...answers,
      [id]: {
        type,
        val,
        isRequired
      }
    })
  }, [answers])

  const handleAddrSubmit = useCallback((type, onSubmit) => {
    addressMethodsObj.current[type] = onSubmit
  }, [])

  const handleSubmit = useCallback(async (e) => {
    const finalData = {}
    let isError = false
    let errorMsg = 'Form survey harus diisi'
    const ansTracker = { ...answers }

    if (isEmpty(answers)) {
      isError = true
    } else {
      const reqIds = [...document.querySelectorAll('.question')]
        .filter((ele) => ele.getAttribute('data-isReq') === 'true')
        .map((ele) => {
          return {
            id: ele.getAttribute('data-qid'),
            type: ele.getAttribute('data-type'),
            restrictWeekday: ele.getAttribute('data-weekday')
          }
        })
      for (let i = 0; i < reqIds.length; i++) {
        if (!(reqIds[i].id in answers)) {
          if (reqIds[i].type === 'TYPE_CHECKBOX_SLIDER') {
            ansTracker[reqIds[i].id] = {
              val: 'False'
            }
            setAnswers({
              ...answers,
              [reqIds[i]]: 'False'
            })
          } else {
            isError = true
            break
          }
        } else if (reqIds[i].type === 'TYPE_DATE_TIME' && reqIds[i].restrictWeekday) {
          // checking if the date and time are between required range
          if (([0, 7].includes(moment(ansTracker[reqIds[i].id].val).isoWeekday()))) {
            errorMsg = LANG_STRINGS.surveyTimingError
            isError = true
          } else {
            const checktime = moment(moment(ansTracker[reqIds[i].id].val).format('HH:mm:ss'), 'HH:mm:ss')
            const minTime = moment('09:00:00', 'HH:mm:ss')
            const maxTime = moment('15:00:00', 'HH:mm:ss')
            if (!checktime.isBetween(minTime, maxTime)) {
              errorMsg = LANG_STRINGS.surveyTimingError
              isError = true
            }
          }
        }
      }
      if (!isError) {
        for (let i = 0; i < reqIds.length; i++) {
          const id = reqIds[i].id
          const ans = ansTracker[id]
          if (ans.type === 'TYPE_ADDRESS') {
            const addr = await addressMethodsObj.current[id](e)
            if (addr) {
              finalData[id] = {
                value: addr
              }
            } else {
              isError = true
              break
            }
          } else {
            finalData[id] = {
              value: ans.val
            }
          }
        }
        return finalData
      }
    }
    if (isError) {
      ShowSnackbar.error({
        visible: true,
        text: errorMsg
      })
    }
  }, [answers])

  useEffect(() => {
    handleGetSubmitMethods('survey-data-form',
      handleSubmit)
  }, [handleGetSubmitMethods, handleSubmit])

  const renderQuestion = useCallback((q) => {
    switch (q.question_type) {
      case 'TYPE_RADIO_VERTICAL':
        return (
          <div
            className='question' key={q.id} data-qid={q.id} data-isReq={q.is_required}
            data-type={q.question_type}
          >
            <CustomText size='10px' color={AgentColorPallette.black} top='4px'>
              {q.question}
            </CustomText>
            {
              q.question_option.map((vop) => (
                <VerticalRadioGroup
                  className='m-tb'
                  key={vop.title}
                  name={vop.title}
                  data={{
                    id: vop.title
                  }}
                  selected={answers[q.id]?.val}
                  onChange={(op) => handleAnsChange(q.id, op.id, q.question_type, q.is_required)}
                  label={
                    <CustomText
                      size='13px'
                      color={AgentColorPallette.black}
                      padLeft='10px'
                    >
                      {vop?.title}
                    </CustomText>
                  }
                  levelRightPosition
                >
                  <div className='v-option'>
                    {
                        vop?.description &&
                          <CustomText
                            size='13px'
                            color={AgentColorPallette.black}
                            dangerouslySetInnerHTML={{
                              __html: vop?.description
                            }}
                          />
                    }
                    {
                      vop.questions.map((qp) => (
                        renderQuestion(qp)
                      ))
                    }
                  </div>
                </VerticalRadioGroup>
              ))
            }
          </div>
        )
      case 'TYPE_ADDRESS':
        return (
          <div
            className='question' key={q.id} data-qid={q.id} data-isReq={q.is_required}
            data-type={q.question_type}
          >
            <AddressForm
              addressType={q.id}
              handleGetAddressSubmit={handleAddrSubmit}
              onAddressChange={(val) => { handleAnsChange(q.id, val, q.question_type, q.is_required) }}
            />
          </div>
        )
      case 'TYPE_CHECKBOX_SLIDER':
      {
        let qs = []
        for (let i = 0; i < q.question_option.length; i++) {
          if ((q.question_option[i].title === answers[q.id]?.val && q.question_option[i].questions) || (answers[q.id]?.val === undefined && q.question_option[i].title === 'False')) {
            qs = q.question_option[i].questions
            break
          }
        }
        return (
          <div
            className='question' key={q.id} data-qid={q.id} data-isReq={q.is_required}
            data-type={q.question_type}
          >
            <Row justify='space-between'>
              <CustomText size='13px' color={AgentColorPallette.black} top='4px'>
                {q.question}
              </CustomText>
              <Switch isChecked={answers[q.id]?.val === 'True'} onChange={() => handleAnsChange(q.id, answers[q.id]?.val === 'True' ? 'False' : 'True', q.question_type, q.is_required)} />
            </Row>
            {
              qs.map((qp) => (
                renderQuestion(qp)
              ))
            }
          </div>
        )
      }
      case 'TYPE_DATE_TIME':
      {
        const dateProps = {
          type: 'datetime-local',
          className: 'datetimerpicker',
          value: answers[q.id]?.val,
          onChange: (e) => { handleAnsChange(q.id, e.target.value, q.question_type, q.is_required) }
        }
        if (q?.constraints?.max_value) {
          dateProps.max = q.constraints.max_value
        }
        if (q?.constraints?.min_value) {
          dateProps.min = q.constraints.min_value
        }
        return (
          <div
            className='question' key={q.id} data-qid={q.id} data-isReq={q.is_required}
            data-type={q.question_type} data-weekday={q?.constraints?.restrict_to_weekdays}
          >
            <CustomText
              size='13px'
              color={AgentColorPallette.regular}
              top='4px'
            >
              {q.question}
            </CustomText>
            <input
              {...dateProps}
            />
          </div>
        )
      }
      default:
    }
  }, [handleAnsChange, answers, handleAddrSubmit])

  return (
    <SurveySectionStyle>
      <CustomText
        color={AgentColorPallette.black}
        size='15px'
        weight={800}
      >
        {LANG_STRINGS.vehicleSurvey}
      </CustomText>
      <div>
        {
          getSurveyFormData && Array.isArray(getSurveyFormData?.questions) && getSurveyFormData?.questions?.map((q) => {
            return renderQuestion(q)
          })
        }
      </div>
      <ShowSnackbar hideOkay />
    </SurveySectionStyle>
  )
}

export default SurveySection
